/* ============================================
   Brazil Map Custom Visual - Modern Styles
   ============================================ */
/* ─── Root ─────────────────────────────────── */
.brazil-map-visual {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  background: transparent;
  box-sizing: border-box;
  color: #252423;
}
/* ─── Content Layout ───────────────────────── */
.bm-content {
  flex: 1;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 8px;
  padding: 6px 10px 10px;
  min-height: 0;
  overflow: hidden;
  box-sizing: border-box;
}
/* ─── Map Panel ────────────────────────────── */
.bm-map-panel {
  flex: 1;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  min-width: 0;
  min-height: 0;
  gap: 6px;
}
/* ─── SVG Wrapper ──────────────────────────── */
.bm-map-wrapper {
  flex: 1;
  min-width: 0;
  min-height: 0;
  position: relative;
  border-radius: 8px;
  overflow: hidden;
}
.bm-svg {
  display: block;
  overflow: visible;
  cursor: grab;
}
.bm-svg:active {
  cursor: grabbing;
}
/* ─── State Paths ──────────────────────────── */
.bm-state-path {
  cursor: pointer;
  shape-rendering: geometricPrecision;
  transition: filter 0.12s ease;
}
.bm-state-path:hover {
  filter: brightness(1.15) saturate(1.15) drop-shadow(0 0 3px rgba(0, 0, 0, 0.25));
}
/* ─── Labels ───────────────────────────────── */
.bm-label {
  text-anchor: middle;
  dominant-baseline: central;
  pointer-events: none;
  user-select: none;
  text-rendering: optimizeLegibility;
}
/* ─── Tooltip ──────────────────────────────── */
.bm-tooltip {
  position: absolute;
  padding: 10px 14px;
  border-radius: 8px;
  pointer-events: none;
  z-index: 1000;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18), 0 2px 6px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(0, 0, 0, 0.08);
  background: #ffffff;
  color: #252423;
  max-width: 240px;
  white-space: normal;
  backdrop-filter: blur(4px);
}
.bm-tt-title {
  font-weight: 600;
  font-size: 0.92em;
  margin-bottom: 5px;
  padding-bottom: 5px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}
.bm-tt-value {
  font-size: 1.05em;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.bm-tt-meta {
  font-size: 0.8em;
  color: #605e5c;
  margin-top: 3px;
}
.bm-tt-pct {
  font-size: 0.82em;
  color: #8a8886;
  margin-top: 2px;
}
/* ─── Data Table ───────────────────────────── */
.bm-data-table {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 115px;
  max-width: 190px;
  overflow-y: auto;
  flex-shrink: 0;
  padding: 2px 4px 2px 0;
}
.bm-data-table::-webkit-scrollbar {
  width: 3px;
}
.bm-data-table::-webkit-scrollbar-track {
  background: transparent;
}
.bm-data-table::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.15);
  border-radius: 2px;
}
.bm-dt-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 5px 8px;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.03);
  border-left: 3px solid transparent;
  transition: background 0.1s ease;
}
.bm-dt-row:hover {
  background: rgba(0, 0, 0, 0.07);
}
.bm-dt-label {
  font-weight: 600;
  font-size: 0.82em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #605e5c;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}
.bm-dt-values {
  display: flex;
  gap: 6px;
  align-items: baseline;
}
.bm-dt-value {
  font-size: 0.97em;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.bm-dt-pct {
  font-size: 0.76em;
  color: #8a8886;
}
.bm-dt-secondary {
  font-size: 0.76em;
  color: #8a8886;
}
.bm-dt-bar-track {
  width: 100%;
  height: 3px;
  background: rgba(0, 0, 0, 0.08);
  border-radius: 2px;
  overflow: hidden;
  margin-top: 2px;
}
.bm-dt-bar-fill {
  height: 100%;
  border-radius: 2px;
  transition: width 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
/* ─── Legend ───────────────────────────────── */
.bm-legend {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  flex-shrink: 0;
  padding: 6px 4px;
  min-width: 36px;
}
.bm-legend-bar {
  width: 10px;
  flex: 1;
  min-height: 80px;
  max-height: 220px;
  border-radius: 5px;
  flex-shrink: 0;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.12);
}
.bm-legend-bar-h {
  width: auto;
  height: 10px;
  min-height: unset;
  max-height: unset;
  min-width: 80px;
  max-width: 220px;
  flex: 1;
}
.bm-legend-title {
  white-space: nowrap;
}
.bm-legend-tick {
  font-size: 0.68em;
  color: inherit;
  line-height: 1;
  text-align: center;
  max-width: 50px;
  word-break: break-all;
  font-variant-numeric: tabular-nums;
}
/* ─── Responsive ───────────────────────────── */
@media (max-width: 400px) {
  .bm-content {
    flex-direction: column;
    padding: 4px 6px 8px;
  }
  .bm-map-panel {
    min-height: 160px;
  }
  .bm-data-table {
    flex-direction: row;
    flex-wrap: wrap;
    max-width: 100%;
    min-width: unset;
    max-height: 80px;
  }
  .bm-legend {
    min-width: unset;
    flex-direction: row;
  }
  .bm-legend-bar {
    width: 80px;
    height: 10px;
    min-height: unset;
    max-height: unset;
    max-width: 180px;
  }
}
